// Combine period with each client
const periodItems = $input.first().json;
const period = $('Последний период').first().json.period;
const clients = $('Активные клиенты с email').all();

return clients.map(c => ({
  json: {
    ...c.json,
    period: period
  }
}));

// Build HTML email report
const currentData = $('Данные SimilarWeb за период').all().map(i => i.json);
const prevData = $('Данные за предыдущий период').all().map(i => i.json);
const clientInfo = $('Loop: по клиентам').first().json;

const period = clientInfo.period;
const clientSite = clientInfo.client_site;
const email = clientInfo.employee_email;

// Helper: format number
function fmtNum(n) {
  if (n == null || n === '') return '—';
  const num = Number(n);
  if (isNaN(num)) return String(n);
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
  return num.toFixed(1);
}

// Helper: format percentage
function fmtPct(n) {
  if (n == null || n === '') return '—';
  return Number(n).toFixed(1) + '%';
}

// Helper: format duration (seconds → m:ss)
function fmtDur(n) {
  if (n == null || n === '') return '—';
  const s = Number(n);
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, '0')}`;
}

// Helper: calculate change
function calcChange(curr, prev) {
  if (!curr || !prev || Number(prev) === 0) return '';
  const change = ((Number(curr) - Number(prev)) / Number(prev)) * 100;
  const arrow = change > 0 ? '↑' : change < 0 ? '↓' : '→';
  const color = change > 0 ? '#27ae60' : change < 0 ? '#e74c3c' : '#7f8c8d';
  return `<span style="color:${color};font-size:12px;">${arrow}${Math.abs(change).toFixed(1)}%</span>`;
}

// Build prev data lookup: site → data
const prevMap = {};
for (const row of prevData) {
  prevMap[row.site] = row;
}

// Separate client and competitors
const clientRow = currentData.find(r => r.site_type === 'client');
const competitorRows = currentData.filter(r => r.site_type === 'competitor');
const allRows = clientRow ? [clientRow, ...competitorRows] : competitorRows;

// Build engagement table rows
let engagementRows = '';
for (const row of allRows) {
  const prev = prevMap[row.site] || {};
  const isClient = row.site_type === 'client';
  const bgColor = isClient ? '#eaf6ff' : '#fff';
  const fontWeight = isClient ? 'bold' : 'normal';

  engagementRows += `
    <tr style="background:${bgColor};">
      <td style="padding:8px 12px;border:1px solid #ddd;font-weight:${fontWeight};">
        ${row.site}${isClient ? ' ⭐' : ''}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtNum(row.monthly_visits)} ${calcChange(row.monthly_visits, prev.monthly_visits)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtNum(row.unique_visitors)} ${calcChange(row.unique_visitors, prev.unique_visitors)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtDur(row.visit_duration)} ${calcChange(row.visit_duration, prev.visit_duration)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtNum(row.pages_per_visit)} ${calcChange(row.pages_per_visit, prev.pages_per_visit)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.bounce_rate)} ${calcChange(row.bounce_rate, prev.bounce_rate)}
      </td>
    </tr>`;
}

// Build channels table rows
let channelsRows = '';
for (const row of allRows) {
  const prev = prevMap[row.site] || {};
  const isClient = row.site_type === 'client';
  const bgColor = isClient ? '#eaf6ff' : '#fff';
  const fontWeight = isClient ? 'bold' : 'normal';

  channelsRows += `
    <tr style="background:${bgColor};">
      <td style="padding:8px 12px;border:1px solid #ddd;font-weight:${fontWeight};">
        ${row.site}${isClient ? ' ⭐' : ''}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.direct)} ${calcChange(row.direct, prev.direct)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.organic_search)} ${calcChange(row.organic_search, prev.organic_search)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.paid_search)} ${calcChange(row.paid_search, prev.paid_search)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.display_ads)} ${calcChange(row.display_ads, prev.display_ads)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.social)} ${calcChange(row.social, prev.social)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.email_channel)} ${calcChange(row.email_channel, prev.email_channel)}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">
        ${fmtPct(row.ai_traffic)} ${calcChange(row.ai_traffic, prev.ai_traffic)}
      </td>
    </tr>`;
}

// Position comparison (rank by monthly visits)
const sorted = [...allRows].sort((a, b) => Number(b.monthly_visits || 0) - Number(a.monthly_visits || 0));
let positionRows = '';
sorted.forEach((row, idx) => {
  const isClient = row.site_type === 'client';
  const bgColor = isClient ? '#eaf6ff' : '#fff';
  const fontWeight = isClient ? 'bold' : 'normal';
  positionRows += `
    <tr style="background:${bgColor};">
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:center;font-weight:bold;">${idx + 1}</td>
      <td style="padding:8px 12px;border:1px solid #ddd;font-weight:${fontWeight};">
        ${row.site}${isClient ? ' ⭐' : ''}
      </td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">${fmtNum(row.monthly_visits)}</td>
      <td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">${fmtPct(row.organic_search)}</td>
    </tr>`;
});

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family:'Segoe UI',Arial,sans-serif;max-width:900px;margin:0 auto;background:#f5f5f5;padding:20px;">
  <div style="background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.1);">

    <!-- Header -->
    <div style="background:linear-gradient(135deg,#2c3e50,#3498db);padding:30px;text-align:center;">
      <h1 style="color:#fff;margin:0;font-size:24px;">📊 Щомісячний звіт SimilarWeb</h1>
      <p style="color:#ecf0f1;margin:8px 0 0;font-size:16px;">${clientSite} — період ${period}</p>
    </div>

    <div style="padding:24px;">

      <!-- Section 1: Engagement -->
      <h2 style="color:#2c3e50;border-bottom:2px solid #3498db;padding-bottom:8px;margin-top:0;">
        📈 Поведінкові метрики
      </h2>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <thead>
            <tr style="background:#34495e;color:#fff;">
              <th style="padding:10px 12px;text-align:left;">Сайт</th>
              <th style="padding:10px 12px;text-align:right;">Візити</th>
              <th style="padding:10px 12px;text-align:right;">Унікальні</th>
              <th style="padding:10px 12px;text-align:right;">Тривалість</th>
              <th style="padding:10px 12px;text-align:right;">Стор./візит</th>
              <th style="padding:10px 12px;text-align:right;">Bounce Rate</th>
            </tr>
          </thead>
          <tbody>${engagementRows}</tbody>
        </table>
      </div>

      <!-- Section 2: Marketing Channels -->
      <h2 style="color:#2c3e50;border-bottom:2px solid #e67e22;padding-bottom:8px;margin-top:28px;">
        🎯 Маркетингові канали
      </h2>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <thead>
            <tr style="background:#34495e;color:#fff;">
              <th style="padding:10px 12px;text-align:left;">Сайт</th>
              <th style="padding:10px 12px;text-align:right;">Direct</th>
              <th style="padding:10px 12px;text-align:right;">Organic</th>
              <th style="padding:10px 12px;text-align:right;">Paid</th>
              <th style="padding:10px 12px;text-align:right;">Display</th>
              <th style="padding:10px 12px;text-align:right;">Social</th>
              <th style="padding:10px 12px;text-align:right;">Email</th>
              <th style="padding:10px 12px;text-align:right;">AI</th>
            </tr>
          </thead>
          <tbody>${channelsRows}</tbody>
        </table>
      </div>

      <!-- Section 3: Position Comparison -->
      <h2 style="color:#2c3e50;border-bottom:2px solid #27ae60;padding-bottom:8px;margin-top:28px;">
        🏆 Рейтинг за трафіком
      </h2>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <thead>
            <tr style="background:#34495e;color:#fff;">
              <th style="padding:10px 12px;text-align:center;">Позиція</th>
              <th style="padding:10px 12px;text-align:left;">Сайт</th>
              <th style="padding:10px 12px;text-align:right;">Візити/міс.</th>
              <th style="padding:10px 12px;text-align:right;">Organic %</th>
            </tr>
          </thead>
          <tbody>${positionRows}</tbody>
        </table>
      </div>

      <!-- Footer -->
      <div style="margin-top:28px;padding-top:16px;border-top:1px solid #eee;text-align:center;color:#7f8c8d;font-size:12px;">
        <p>Стрілки показують динаміку відносно попереднього періоду<br>
        <span style="color:#27ae60;">↑ покращення</span> · 
        <span style="color:#e74c3c;">↓ погіршення</span> · 
        <span style="color:#7f8c8d;">→ без змін</span></p>
        <p>Дані: SimilarWeb | Звіт згенеровано автоматично</p>
      </div>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    to: email,
    subject: `📊 SimilarWeb звіт: ${clientSite} — ${period}`,
    html: html,
    client_site: clientSite,
    period: period
  }
}];
